"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["89705"],{50614(e){e.exports=JSON.parse('{"id":"FIN-607","slug":"financial-close","term":"Financial Close","also_known_as":[],"difficulty":"Intermediate","definition":"Financial close is the process a company\'s finance team follows at the end of each accounting period to finalise its records, make adjustments and prepare financial statements.","explanation":["At the end of each month, quarter and year, accountants must make sure all transactions have been recorded correctly before reporting results. This process is called the financial close, or simply \\"the close\\".","Typical steps include recording all invoices and receipts; reconciling bank accounts and key balance sheet accounts; recording accruals, prepayments and depreciation; reviewing estimates such as bad debt allowances; eliminating transactions between group companies; and producing the trial balance and financial statements for review.","For example, a company might aim to close its books within five working days after each month-end, so managers have up-to-date results quickly.","A fast and accurate close is valuable. It gives managers timely information for decisions and reduces the risk of errors in published accounts. Slow or chaotic closes can signal weak processes or controls.","The year-end close is usually the most demanding, because it involves additional adjustments, detailed reviews and support for the external auditors. Many companies use checklists, close calendars and accounting software to make the process consistent and efficient."],"note":"","total":1725,"prev":{"slug":"financial-buyer","term":"Financial Buyer"},"next":{"slug":"financial-conduct-authority","term":"Financial Conduct Authority (FCA)"}}')}}]);